// Angsuran tunggak (tgl_angsuran <= tanggal_tebus) yang TIDAK dipilih untuk
// dibayar. Server hanya mewajibkan minimal satu angsuran tunggak dipilih, jadi
// sisanya dikonfirmasi setiap aksi workflow maju.
export function angsuranTunggakTidakDibayar(doc) {
	const batas = doc?.tanggal_tebus
	if (!batas) return []
	return (doc.tabel_angsuran_tebus || []).filter(
		(row) => !row.pilih && row.tgl_angsuran && row.tgl_angsuran <= batas
	)
}
